(async()=>{
const model=globalThis.ProofKeyIntakeModel;
const {openStore,prepareFile}=globalThis.ProofKeyIntakeStore;
const $=id=>document.getElementById(id),status=$('status');
let store,current,staged=[],urls=[],busy=false,selection=0;
const text=(tag,value,parent,cls)=>{const el=document.createElement(tag);el.textContent=value;if(cls)el.className=cls;if(parent)parent.append(el);return el;};
function report(message,error=false){status.textContent=message;status.className=error?'error':'';}
function cleanup(){urls.forEach(URL.revokeObjectURL);urls=[];}
function preview(asset,parent){const url=URL.createObjectURL(asset.blob);urls.push(url);if(asset.media.mime_type.startsWith('image/')){const img=document.createElement('img');img.src=url;img.alt=asset.name;img.className='preview';parent.append(img);}else{const audio=document.createElement('audio');audio.src=url;audio.controls=true;audio.preload='metadata';parent.append(audio);text('small','Audio preview only. No transcription or analysis.',parent);}}
function disable(value){busy=value;document.querySelectorAll('button,input,select,textarea').forEach(el=>{el.disabled=value;});}
async function refreshList(){const list=$('case-list');list.replaceChildren();for(const c of await store.list()){const li=text('li','',list);const a=text('a',`${c.title} (${c.id})`,li);a.href=`?case=${encodeURIComponent(c.id)}`;}if(!list.children.length)text('li','No cases saved yet.',list);}
async function show(id){cleanup();current=await store.get(id);const detail=$('detail');detail.replaceChildren();if(!current){text('p','Case not found in this browser.',detail).id='missing-case';return;}
 text('h2',current.title,detail);text('p',`${current.id} · Revision ${current.revision} · Analysis pending, not started`,detail);text('p',`Order ${current.declaration.links.order_id} · ${current.declaration.participants.join(', ')}`,detail);
 const form=document.createElement('form');form.id='evidence-form';form.innerHTML='<h3>Add evidence</h3><label>Message or attachment note<textarea id="message" maxlength="4096" rows="3"></textarea></label><label>Sender<select id="sender"></select></label><label>Evidence occurred at (ISO timestamp with timezone)<input id="occurred-at" required maxlength="64"></label><label>Channel<select id="channel"><option>chat</option><option>email</option><option>phone</option><option>internal</option></select></label><label>Audio evidence type<select id="audio-kind"><option value="voice_message">Voice message</option><option value="call_recording">Call recording</option></select></label><label>Photos or audio<input type="file" id="files" multiple accept="image/png,image/jpeg,audio/mpeg,audio/wav,audio/mp4,audio/webm"></label><small>PNG/JPEG: 10 MiB each. MPEG/WAV/MP4/WebM audio: 25 MiB each. Total local file storage: 100 MiB. Saving does not upload or analyse files.</small><div id="staged" aria-live="polite"></div><button id="save-evidence" type="submit">Save evidence locally</button>';
 detail.append(form);$('occurred-at').value=new Date().toISOString();for(const id of current.declaration.participants){const option=text('option',id,$('sender'));option.value=id;}
 $('files').addEventListener('change',selectFiles);form.addEventListener('submit',saveEvidence);
 const exportButton=text('button','Export payloads and local manifest',detail,'secondary');exportButton.type='button';exportButton.addEventListener('click',exportCase);
 text('h3','Committed history',detail);const history=text('div','',detail);history.id='history';for(const event of current.events){const article=text('article','',history);text('h4',`${event.kind} · ${event.event_id}`,article);text('p',`${event.sender_id} · ${event.occurred_at}`,article);if(event.text)text('p',event.text,article);if(event.media){const asset=await store.asset(event.media.asset_id);if(asset){text('p',asset.name,article);preview(asset,article);text('small',`SHA-256 ${asset.media.sha256}`,article);}else text('p','Attachment unavailable',article,'error');}}
}
function renderStaged(){const target=$('staged');target.replaceChildren();for(const item of staged){const row=text('div','',target,'file-row');text('strong',item.name,row);text('p',item.error||'Ready to save locally',row,item.error?'error':'');if(item.asset){row.dataset.ready='true';text('small',`${item.asset.media.size_bytes} bytes · SHA-256 ${item.asset.media.sha256}`,row);}const remove=text('button','Remove',row,'secondary');remove.type='button';remove.addEventListener('click',()=>{staged=staged.filter(x=>x!==item);renderStaged();});}}
async function selectFiles(){const token=++selection,files=Array.from($('files').files);const total=staged.reduce((sum,item)=>sum+(item.asset?.blob.size||0),0)+files.reduce((sum,file)=>sum+file.size,0);if(total>model.LIMITS.total||staged.length+files.length+current.events.length>model.LIMITS.events){$('files').value='';report('Draft exceeds 100 MiB or the 128-event case limit. Select fewer files.',true);return;}disable(true);for(const file of files){const item={name:file.name};staged.push(item);try{item.asset=await prepareFile(file);if(staged.some(x=>x!==item&&x.asset?.media.sha256===item.asset.media.sha256)){delete item.asset;throw Error('Duplicate selected file');}}catch(error){item.error=error.message;}if(token!==selection)return;renderStaged();}disable(false);$('files').value='';report('File validation finished. Remove rejected files before saving.');}
async function saveEvidence(event){event.preventDefault();if(busy)return;const message=$('message').value;const sender=$('sender').value,channel=$('channel').value,audioKind=$('audio-kind').value;if(staged.some(x=>!x.asset)){report('Remove rejected files before saving.',true);return;}if(!message.trim()&&!staged.length){report('Add a message or a valid file.',true);return;}disable(true);try{const assets=staged.map(x=>x.asset);const base={occurred_at:$('occurred-at').value,channel,sender_id:sender,recipient_ids:current.declaration.participants.filter(x=>x!==sender)};const events=assets.map(a=>({...base,event_id:'event-'+crypto.randomUUID(),kind:a.kind==='photo'?'photo':audioKind,text:message||null,media:a.media}));if(!assets.length)events.push({...base,event_id:'event-'+crypto.randomUUID(),kind:'message',text:message,media:null});await store.append(current.id,current.revision,events,assets);staged=[];await show(current.id);await refreshList();report('Evidence saved locally. Analysis has not started.');}catch(error){report(`Not saved: ${error.message}. Your draft is retained.`,true);}finally{disable(false);}}
async function exportCase(){const manifest=[];for(const e of current.events){if(e.media){const a=await store.asset(e.media.asset_id);manifest.push({...e.media,filename:a?.name,storage:'browser-local IndexedDB',extraction:'not_started'});}}const output={format:'right-ontime-local-export-v1',declaration:current.declaration,append_payloads:current.events.map((event,i)=>({expected_revision:i,event})),local_attachment_manifest:manifest,notice:'Metadata only; file bytes remain in this browser. No server upload, analysis, authority or operational effect.'};const url=URL.createObjectURL(new Blob([JSON.stringify(output,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`${current.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('create-form').addEventListener('submit',async event=>{event.preventDefault();if(busy)return;disable(true);try{const customer=$('customer-id').value,operator=$('operator-id').value;const declaration={case_id:$('case-id').value,links:{order_id:$('order-id').value,customer_id:customer,operator_id:operator},participants:[customer,operator,...$('extra-participants').value.split(',').map(x=>x.trim()).filter(Boolean)],language:'en'};await store.create(declaration,$('case-title').value);staged=[];history.replaceState(null,'',`?case=${encodeURIComponent(declaration.case_id)}`);await refreshList();await show(declaration.case_id);$('create-form').reset();report('Case saved locally at revision 0.');}catch(error){report(`Not saved: ${error.message}. Your draft is retained.`,true);}finally{disable(false);}});
window.addEventListener('pagehide',cleanup);
try{store=await openStore();window.ProofKeyIntake={...model,prepareFile,store};await refreshList();const id=new URLSearchParams(location.search).get('case');if(id)await show(id);report('Local storage ready.');}catch(error){report(`Local storage unavailable: ${error.message}. Nothing has been saved.`,true);disable(true);}
})();
